frame.store("_a_word_not_a_name", { let __signature_4194 = Signature { name: "_a_word_not_a_name".into(), positional: vec!["low".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_4196 = Value::dict(); __attrs_4196.dict_set(Value::from("__doc__"), Value::from("Whether a word after \"is\" says how somebody is rather than what they are called.\n\n    A name put right is read from the word after \"is\" (\"she is rosie\"), and that is also how a\n    person says everything else about somebody: \"she is blonde\", \"she is twelve\", \"she is\n    tired\", \"she is married\". Without this the correction reader kept Blonde as a person's name\n    and said \"Blonde, not Amy - got it\", the same open class as \"im blonde\" was for the\n    introduction reader. The colours and the numbers written out have no ending to catch them,\n    so they are listed; the states, the conditions and the nationalities are the ones the\n    introduction reader already knows by their ending or by name.\n    "))?; __attrs_4196.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_4197 = Value::dict(); __attrs_4196.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_4193 = Frame::module(frame.globals.clone()); let mut __function_4195 = NativeFunction::qualified_with_origin("_a_word_not_a_name".into(), "_a_word_not_a_name".into(), "bot.memory.facts".into(), __attrs_4196, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/facts.py", first: 4587, last: 4599, qualname: "_a_word_not_a_name" }, closure: __closure_4193.clone(), freevars: vec![] }, move |rt, args| __py_83::_a_word_not_a_name(rt, __closure_4193.clone(), &__signature_4194, args)); __function_4195 })?;
