frame.store("_the_state_compared", { let __signature_4209 = Signature { name: "_the_state_compared".into(), positional: vec!["word".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_4211 = Value::dict(); __attrs_4211.dict_set(Value::from("__doc__"), Value::from("The state a comparison is written in, or None: \"happier\" is happy, \"sadder\" is sad.\n\n    The endings table has no room for -er and -est: it answers what a word is built with, and\n    \"er\" is Peter's ending as much as it is a comparison's, so nothing in the name reader could\n    tell \"im happier\" from an introduction and each of them was welcomed by name (agile-jay).\n    Only a stem that is a state counts, which is what keeps \"im peter\" and \"im heather\" names.\n    \"happier\" keeps the y it lost as an i, and \"sadder\" carries the doubled consonant English\n    puts in front of -er, so both are put back before the stem is asked about.\n    "))?; __attrs_4211.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_4212 = Value::dict(); __attrs_4211.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_4208 = Frame::module(frame.globals.clone()); let mut __function_4210 = NativeFunction::qualified_with_origin("_the_state_compared".into(), "_the_state_compared".into(), "bot.memory.facts".into(), __attrs_4211, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/facts.py", first: 4608, last: 4628, qualname: "_the_state_compared" }, closure: __closure_4208.clone(), freevars: vec![] }, move |rt, args| __py_84::_the_state_compared(rt, __closure_4208.clone(), &__signature_4209, args)); __function_4210 })?;
