frame.store("not_had", { let __signature_4835 = Signature { name: "not_had".into(), positional: vec!["text".into(),"start".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_4837 = Value::dict(); __attrs_4837.dict_set(Value::from("__doc__"), Value::from("True when the line says the pet at `start` is not, or no longer, theirs.\n\n    Only possession counts. \"i dont have a cat\" takes the cat back; \"i dont like my cat today\"\n    and \"i dont want a dog\" are about how they feel about it, not about what lives in the house,\n    and nothing later puts a pet back, so the narrow reading is the safe one.\n    "))?; __attrs_4837.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_4838 = Value::dict(); __attrs_4837.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_4834 = Frame::module(frame.globals.clone()); let mut __function_4836 = NativeFunction::qualified_with_origin("not_had".into(), "not_had".into(), "bot.memory.facts".into(), __attrs_4837, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/facts.py", first: 6081, last: 6097, qualname: "not_had" }, closure: __closure_4834.clone(), freevars: vec![] }, move |rt, args| __py_129::not_had(rt, __closure_4834.clone(), &__signature_4835, args)); __function_4836 })?;
frame.store("_have_none", { let __signature_4840 = Signature { name: "_have_none".into(), positional: vec!["clause".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_4842 = Value::dict(); __attrs_4842.dict_set(Value::from("__doc__"), Value::from("Whether the clause says the animal is not theirs, read without a bare verb deciding it.\n\n    \"i have got no dog\" and \"we have no pets now\" name the animal as the thing that is gone, so\n    they are the take-back `NOT_HAVE` takes them for. \"he has never liked it\" names no animal\n    after the negation at all, and \"he has no dog friends\" names one that is not the dog: both\n    are things the person is saying about the animal, and neither makes it stop being theirs.\n    "))?; __attrs_4842.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_4843 = Value::dict(); __attrs_4842.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_4839 = Frame::module(frame.globals.clone()); let mut __function_4841 = NativeFunction::qualified_with_origin("_have_none".into(), "_have_none".into(), "bot.memory.facts".into(), __attrs_4842, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/facts.py", first: 6100, last: 6112, qualname: "_have_none" }, closure: __closure_4839.clone(), freevars: vec![] }, move |rt, args| __py_130::_have_none(rt, __closure_4839.clone(), &__signature_4840, args)); __function_4841 })?;
